import { useState } from "react";
import { chatWithProviderConfiguration } from "../../services/llmProviderService";
import { AIBubble, ChatContainer, ChatInput, HumanBubble, Markdown, PresetPrompts, TypingIndicator } from "../playground";

// Test chat for one saved configuration: the reply is generated by the provider with that configuration's credential,
// model, settings and parameters. The conversation lives in the parent so it survives switching tabs.
const PRESETS = [
  "Say hello and tell me which model you are.",
  "Compare REST and GraphQL in a table with pros and cons.",
  "Explain merge sort with a short code example.",
];

export default function ProviderChat({ provider, configuration, dirty, messages, setMessages, isLight }) {
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");

  const muted = isLight ? "text-gray-500" : "text-[#8B98A8]";
  const ready = Boolean(configuration);
  const missing = ready && !configuration.model ? "Choose a model in this configuration first." : null;

  const handleSubmit = async (text) => {
    if (sending || !ready || missing) return;
    const next = [...messages, { role: "user", content: text }];
    setMessages(next);
    setError("");
    setSending(true);
    try {
      // only roles and text go up; usage and error notes are display-only
      const history = next.filter((m) => m.role === "user" || m.role === "assistant").map(({ role, content }) => ({ role, content }));
      const reply = await chatWithProviderConfiguration(provider.id, configuration.id, history);
      setMessages([...next, { role: "assistant", content: reply.content, usage: reply.usage }]);
    } catch (err) {
      setError(err.message || "The provider could not generate a response.");
    } finally {
      setSending(false);
    }
  };

  if (!ready) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 px-8 text-center">
        <p className="m-0 text-[14px] font-semibold">No configuration to test</p>
        <p className={`m-0 text-[13px] leading-snug ${muted}`}>Save a configuration on the Configuration tab, then come back here to chat with it.</p>
      </div>
    );
  }

  const tokens = (usage) => (usage?.total_tokens ? `${usage.total_tokens} tokens` : null);

  return (
    <ChatContainer
      isLight={isLight}
      header={
        <>
          <span className="block truncate text-[13.5px] font-semibold">{configuration.name}</span>
          <span className={`block truncate text-[11.5px] ${muted}`}>{configuration.model || "no model selected"}</span>
          {dirty && <p className="m-0 mt-2 text-[12px] text-amber-500">You have unsaved changes. The chat uses the saved version.</p>}
          {missing && <p className="m-0 mt-2 text-[12px] text-rose-500">{missing}</p>}
        </>
      }
      input={
        <ChatInput
          isLight={isLight}
          onSubmit={handleSubmit}
          disabled={sending || Boolean(missing)}
          placeholder={missing ? "Fix the configuration to chat" : "Type a message…"}
          onNewThread={messages.length > 0 ? () => { setMessages([]); setError(""); } : undefined}
        />
      }
    >
      {messages.length === 0 && !sending && (
        <PresetPrompts
          isLight={isLight}
          title="Try this configuration"
          description={`Ask anything. The reply comes from ${provider.name} using the saved key, model and settings.`}
          prompts={PRESETS}
          onSelect={handleSubmit}
          disabled={Boolean(missing)}
        />
      )}

      {messages.map((m, i) =>
        m.role === "user" ? (
          <HumanBubble key={i} isLight={isLight}>
            <Markdown isLight={isLight}>{m.content}</Markdown>
          </HumanBubble>
        ) : (
          <AIBubble key={i} label={provider.name} footer={tokens(m.usage)} isLight={isLight}>
            <Markdown isLight={isLight}>{m.content}</Markdown>
          </AIBubble>
        )
      )}

      {sending && <TypingIndicator label={provider.name} isLight={isLight} />}
      {error && <p className="m-0 border border-rose-500/40 px-3 py-2.5 text-[12.5px] leading-snug text-rose-500">{error}</p>}
    </ChatContainer>
  );
}
